void bluemapViewBase::handleTickEvent()
{
    frameCountUPdate2Interval++;
    if(frameCountUPdate2Interval == TICK_UPDATE2_INTERVAL)
    {
        //UPdate2
        //When every N tick call virtual function
        //Call update2
        update2();
        frameCountUPdate2Interval = 0;
    }
}
